(6725526, 1005441, 16106, '<td valign="top">Great contrast in colors, but this feels in between; closer in to show more bird, or further back to show more tree with the bird as a bright accent would work for me.</td>', 'Great contrast in colors, but this feels in between; closer in to show more bird, or further back to show more tree with the bird as a bright accent would work for me.', '2012-03-28 18:59:19.000000', NULL, 1),
(6725529, 1006410, 16106, '<td valign="top">I love the shapes here, but I wish you had a bit more color to show us this isn''t a de-saturation, a little play of blue and yellow tones would have gone a long way.</td>', 'I love the shapes here, but I wish you had a bit more color to show us this isn''t a de-saturation, a little play of blue and yellow tones would have gone a long way.', '2012-03-28 19:01:26.000000', NULL, 1),
(6725531, 1006224, 16106, '<td valign="top">A bit on the fuzzy/dim side on my monitor, but the best subject and color match yet. Nice job... mostly. A touch more contrast and sharpening and this would be a sure ribbon winner.</td>', 'A bit on the fuzzy/dim side on my monitor, but the best subject and color match yet. Nice job... mostly. A touch more contrast and sharpening and this would be a sure ribbon winner.', '2012-03-28 19:04:15.000000', NULL, 1),
